params.css:
#sheet > *{margin-left:8%;margin-right:2%;text-align:right;width:auto;max-width:none;}
#sheet .inner > *{margin-left:8%;margin-right:2%;text-align:right;width:auto;max-width:none;}
#sheet main > *{margin-left:8%;margin-right:2%;text-align:right;width:auto;max-width:none;}
#sheet .frame > *{margin-left:8%;margin-right:2%;text-align:right;width:auto;max-width:none;}
#sheet .card > *{margin-left:8%;margin-right:2%;text-align:right;width:auto;max-width:none;}
#sheet > *:nth-child(odd){margin-left:18%;}
#sheet .inner > *:nth-child(odd){margin-left:18%;}
#sheet main > *:nth-child(odd){margin-left:18%;}
#sheet .frame > *:nth-child(odd){margin-left:18%;}
#sheet .card > *:nth-child(odd){margin-left:18%;}
#sheet > *:nth-child(n+4){margin-left:26%;}
#sheet .inner > *:nth-child(n+4){margin-left:26%;}
#sheet main > *:nth-child(n+4){margin-left:26%;}
#sheet .frame > *:nth-child(n+4){margin-left:26%;}
#sheet .card > *:nth-child(n+4){margin-left:26%;}
#sheet table.items{text-align:right;}
#sheet .inner table.items{text-align:right;}
#sheet main table.items{text-align:right;}
#sheet .frame table.items{text-align:right;}
#sheet .card table.items{text-align:right;}
#sheet table.items th:first-child{text-align:left;}
#sheet .inner table.items th:first-child{text-align:left;}
#sheet main table.items th:first-child{text-align:left;}
#sheet .frame table.items th:first-child{text-align:left;}
#sheet .card table.items th:first-child{text-align:left;}
#sheet table.items td:first-child{text-align:left;}
#sheet .inner table.items td:first-child{text-align:left;}
#sheet main table.items td:first-child{text-align:left;}
#sheet .frame table.items td:first-child{text-align:left;}
#sheet .card table.items td:first-child{text-align:left;}
#sheet .frame{border-width:.2mm;border-style:double;}
#sheet .inner .frame{border-width:.2mm;border-style:double;}
#sheet main .frame{border-width:.2mm;border-style:double;}
#sheet .frame .frame{border-width:.2mm;border-style:double;}
#sheet .card .frame{border-width:.2mm;border-style:double;}
#sheet > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .inner > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet main > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .frame > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .card > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet table.items{table-layout:fixed;}
#sheet .inner table.items{table-layout:fixed;}
#sheet main table.items{table-layout:fixed;}
#sheet .frame table.items{table-layout:fixed;}
#sheet .card table.items{table-layout:fixed;}
#sheet table.items th{overflow-wrap:anywhere;}
#sheet .inner table.items th{overflow-wrap:anywhere;}
#sheet main table.items th{overflow-wrap:anywhere;}
#sheet .frame table.items th{overflow-wrap:anywhere;}
#sheet .card table.items th{overflow-wrap:anywhere;}
#sheet table.items td{overflow-wrap:anywhere;}
#sheet .inner table.items td{overflow-wrap:anywhere;}
#sheet main table.items td{overflow-wrap:anywhere;}
#sheet .frame table.items td{overflow-wrap:anywhere;}
#sheet .card table.items td{overflow-wrap:anywhere;}
#sheet > .frame,#sheet .frame > .frame,#sheet > .card,#sheet .frame > .card,#sheet > .inner,#sheet .frame > .inner{margin-left:0;margin-right:0;background:transparent;color:inherit;}
